from __future__ import annotations

import copy
import hashlib
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


SCHEMA_VERSION = "work-definition/v1"
FACT_STATUSES = {"confirmed", "inferred", "unknown", "conflicting"}
SCALAR_FACT_FIELDS = ("goal", "trigger", "frequency_volume", "sla", "automation_intent")
LIST_FIELDS = (
    "scope_in",
    "scope_out",
    "actors",
    "systems",
    "inputs",
    "outputs",
    "steps",
    "decisions",
    "exceptions",
    "pains",
    "risks_controls",
    "constraints",
    "success_criteria",
    "assumptions",
    "unresolved",
)


def _payload(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, (dict, list)):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, (dict, list)):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if isinstance(text, str) and text.strip():
        candidate = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)
        return json.loads(candidate)
    return None


def _unwrap_named(payload: Any, *names: str) -> dict[str, Any]:
    if not isinstance(payload, dict):
        return {}
    for name in names:
        nested = payload.get(name)
        if isinstance(nested, dict):
            return copy.deepcopy(nested)
    return copy.deepcopy(payload)


def _safe_id(value: Any, prefix: str, material: str) -> str:
    supplied = re.sub(r"[^A-Za-z0-9_.:-]+", "-", str(value or "").strip())[:200].strip("-")
    if supplied:
        return supplied
    return f"{prefix}-{hashlib.sha256(material.encode('utf-8')).hexdigest()[:20]}"


def _evidence_ids(value: Any, fallback_turn: str) -> list[str]:
    raw = value if isinstance(value, list) else []
    result: list[str] = []
    for item in raw + ([fallback_turn] if fallback_turn else []):
        text = str(item or "").strip()[:200]
        if text and text not in result:
            result.append(text)
    return result[:50]


def _fact(value: Any, *, revision: int, turn_id: str, existing: Any = None) -> dict[str, Any]:
    if isinstance(existing, dict) and existing.get("status") in FACT_STATUSES and "value" in existing:
        prior = copy.deepcopy(existing)
    else:
        prior = None
    source = value if isinstance(value, dict) and "value" in value else {"value": value}
    supplied_value = source.get("value")
    if supplied_value in (None, "", [], {}):
        if prior is not None:
            return prior
        return {
            "value": None,
            "status": "unknown",
            "evidence_turn_ids": [],
            "confidence": 0.0,
            "last_updated_revision": revision,
        }
    if prior is not None and prior.get("status") in {"confirmed", "conflicting"}:
        # A model-normalization stage cannot replace user-confirmed evidence.
        return prior
    requested_status = str(source.get("status") or "inferred").lower()
    status = requested_status if requested_status in {"inferred", "unknown", "conflicting"} else "inferred"
    try:
        confidence = float(source.get("confidence", 0.7 if status == "inferred" else 0.0))
    except (TypeError, ValueError):
        confidence = 0.0
    return {
        "value": copy.deepcopy(supplied_value),
        "status": status,
        "evidence_turn_ids": _evidence_ids(source.get("evidence_turn_ids"), turn_id),
        "confidence": max(0.0, min(confidence, 1.0)),
        "last_updated_revision": revision,
    }


def _list_item(item: Any, *, field: str, index: int, work_id: str, revision: int, turn_id: str) -> dict[str, Any]:
    record = copy.deepcopy(item) if isinstance(item, dict) else {"value": copy.deepcopy(item)}
    identity = record.get("id") or record.get(f"{field[:-1]}_id") or record.get("step_id") or record.get("name") or record.get("label") or record.get("title") or record.get("value")
    item_id = _safe_id(identity, field.rstrip("s") or "item", f"{work_id}|{field}|{index}|{json.dumps(record, sort_keys=True, ensure_ascii=False, default=str)}")
    record.setdefault("id", item_id)
    supplied_provenance = record.get("provenance") if isinstance(record.get("provenance"), dict) else {}
    requested_status = str(supplied_provenance.get("status") or record.pop("status", "inferred")).lower()
    try:
        confidence = float(supplied_provenance.get("confidence", 0.7))
    except (TypeError, ValueError):
        confidence = 0.0
    record["provenance"] = {
        "status": requested_status if requested_status in {"inferred", "unknown", "conflicting"} else "inferred",
        "evidence_turn_ids": _evidence_ids(supplied_provenance.get("evidence_turn_ids") or record.pop("evidence_turn_ids", []), turn_id),
        "confidence": max(0.0, min(confidence, 1.0)),
        "last_updated_revision": revision,
    }
    return record


def _merge_lists(candidate: Any, existing: Any, *, field: str, work_id: str, revision: int, turn_id: str) -> list[dict[str, Any]]:
    prior = copy.deepcopy(existing) if isinstance(existing, list) else []
    incoming = candidate if isinstance(candidate, list) else ([] if candidate in (None, "") else [candidate])
    by_id: dict[str, dict[str, Any]] = {}
    order: list[str] = []
    for index, item in enumerate(prior):
        if not isinstance(item, dict):
            item = {"value": item}
        normalized = copy.deepcopy(item)
        item_id = _safe_id(normalized.get("id"), field.rstrip("s") or "item", f"{work_id}|{field}|prior|{index}")
        normalized["id"] = item_id
        by_id[item_id] = normalized
        order.append(item_id)
    for index, item in enumerate(incoming):
        normalized = _list_item(item, field=field, index=index, work_id=work_id, revision=revision, turn_id=turn_id)
        item_id = normalized["id"]
        prior_item = by_id.get(item_id)
        prior_status = ((prior_item or {}).get("provenance") or {}).get("status") if isinstance(prior_item, dict) else None
        if prior_item is not None and prior_status in {"confirmed", "conflicting"}:
            continue
        by_id[item_id] = normalized
        if item_id not in order:
            order.append(item_id)
    return [by_id[item_id] for item_id in order]


def normalize_work_definition(candidate_value: Any, envelope_value: Any, existing_value: Any = None) -> dict[str, Any]:
    try:
        candidate = _unwrap_named(_payload(candidate_value), "work_definition", "candidate")
        envelope = _unwrap_named(_payload(envelope_value), "envelope")
        existing = _unwrap_named(_payload(existing_value), "work_definition") if existing_value is not None else {}
    except (TypeError, ValueError, json.JSONDecodeError):
        candidate, envelope, existing = {}, {}, {}
    trace_id = f"trace-{uuid.uuid4()}"
    required_envelope = ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode", "source_request")
    missing = [key for key in required_envelope if not envelope.get(key)]
    if missing or not isinstance(candidate, dict):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {
                "code": "WORK_DEFINITION_INPUT_INVALID",
                "message": "업무 정의 후보 또는 요청 Envelope가 유효하지 않습니다.",
                "retryable": False,
                "details": {"missing_envelope_fields": missing},
            },
            "resume": None,
            "trace_id": trace_id,
        }

    work_id = str(envelope["work_definition_id"])
    if existing and any(str(existing.get(key, "")) != str(envelope.get(key, "")) for key in ("work_definition_id", "tenant_id", "owner_id", "session_id", "channel_mode")):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_IDENTITY_MISMATCH", "message": "기존 업무 정의와 요청의 tenant/session 식별자가 다릅니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        revision = int(existing.get("revision", envelope.get("expected_revision", 0)) or 0)
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_REVISION_INVALID", "message": "WorkDefinition revision은 0 이상의 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    if revision < 0:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_REVISION_INVALID", "message": "WorkDefinition revision은 0 이상의 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }
    source = envelope.get("source_request") if isinstance(envelope.get("source_request"), dict) else {}
    turn_id = str(source.get("turn_id") or "")
    document: dict[str, Any] = {
        "schema_version": SCHEMA_VERSION,
        "work_definition_id": work_id,
        "tenant_id": str(envelope["tenant_id"]),
        "owner_id": str(envelope["owner_id"]),
        "session_id": str(envelope["session_id"]),
        "channel_mode": str(envelope["channel_mode"]),
        "revision": revision,
        "status": "EXTRACTING",
        "source_requests": copy.deepcopy(existing.get("source_requests", [])) if isinstance(existing.get("source_requests"), list) else [],
        "preview_hash": existing.get("preview_hash"),
        "approved_hash": existing.get("approved_hash"),
        "as_is_graph": copy.deepcopy(existing.get("as_is_graph") or candidate.get("as_is_graph") or {"nodes": [], "edges": []}),
        "processed_answer_batches": copy.deepcopy(existing.get("processed_answer_batches", [])),
    }
    if source and not any(item.get("turn_id") == turn_id for item in document["source_requests"] if isinstance(item, dict)):
        document["source_requests"].append(copy.deepcopy(source))

    for field in SCALAR_FACT_FIELDS:
        document[field] = _fact(candidate.get(field), revision=revision, turn_id=turn_id, existing=existing.get(field))
    for field in LIST_FIELDS:
        document[field] = _merge_lists(candidate.get(field), existing.get(field), field=field, work_id=work_id, revision=revision, turn_id=turn_id)

    # Keep only explicitly namespaced extensions; arbitrary model output does
    # not become an executable or trusted WorkDefinition field.
    extensions = candidate.get("extensions")
    if isinstance(extensions, dict):
        document["extensions"] = copy.deepcopy(extensions)

    return {
        "ok": True,
        "status": document["status"],
        "artifact_refs": [{"kind": "work_definition", "id": work_id, "revision": revision}],
        "work_definition": document,
        "trace_id": trace_id,
    }


class WorkDefinitionNormalizerComponent(Component):
    display_name = "11 업무 정의 정규화"
    description = "모델의 JSON 후보를 stable ID와 provenance가 있는 WorkDefinition v1으로 결정론적으로 정규화합니다."
    icon = "Braces"
    name = "WorkDefinitionNormalizer"

    inputs = [
        DataInput(name="candidate", display_name="모델 추출 후보", input_types=["Data", "Message", "JSON"], required=True),
        DataInput(name="request_envelope", display_name="업무 요청 Envelope", input_types=["Data", "JSON"], required=True),
        DataInput(name="existing_work_definition", display_name="기존 WorkDefinition", input_types=["Data", "JSON"], required=False, advanced=True),
    ]
    outputs = [Output(name="work_definition", display_name="정규화 WorkDefinition", method="build_work_definition", types=["Data"])]

    def build_work_definition(self) -> Data:
        result = normalize_work_definition(
            getattr(self, "candidate", None),
            getattr(self, "request_envelope", None),
            getattr(self, "existing_work_definition", None),
        )
        self.status = {"ok": result["ok"], "status": result["status"]}
        return Data(data=result)

from __future__ import annotations

"""Fail-closed routing for standalone Langflow component result envelopes."""

import copy
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema import Data


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return copy.deepcopy(value)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return copy.deepcopy(data)
    text = getattr(value, "text", value if isinstance(value, str) else "")
    if not isinstance(text, str) or not text.strip():
        return {}
    parsed = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE))
    return copy.deepcopy(parsed) if isinstance(parsed, dict) else {}


def _field(payload: dict[str, Any], path: str) -> Any:
    current: Any = payload
    for token in [item.strip() for item in path.split(".") if item.strip()]:
        if not isinstance(current, dict) or token not in current:
            return None
        current = current[token]
    return current


def gate_result(value: Any, *, required_field: Any = "") -> dict[str, Any]:
    """Return a canonical success/failure envelope without trusting truthy values."""

    trace_id = f"trace-{uuid.uuid4()}"
    try:
        payload = _payload(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        payload = {}
    required = str(required_field or "").strip()
    if payload.get("ok") is True and (not required or _field(payload, required) not in (None, "")):
        return payload
    if payload.get("ok") is False and isinstance(payload.get("error"), dict):
        return payload
    code = "RESULT_REQUIRED_FIELD_MISSING" if payload.get("ok") is True and required else "RESULT_ENVELOPE_INVALID"
    message = (
        f"성공 결과에 필수 필드 '{required}'가 없습니다."
        if code == "RESULT_REQUIRED_FIELD_MISSING"
        else "이전 단계가 명시적인 ok=true 결과를 반환하지 않았습니다."
    )
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {
            "code": code,
            "message": message,
            "retryable": False,
            "details": {"required_field": required} if required else {},
        },
        "resume": None,
        "trace_id": str(payload.get("trace_id") or trace_id)[:200],
    }


class ResultGateComponent(Component):
    display_name = "35 Result Gate"
    description = "ok=true와 필수 payload 필드를 확인하고 성공·차단 경로를 물리적으로 분리합니다."
    icon = "ShieldCheck"
    name = "ResultGate"

    inputs = [
        DataInput(name="result", display_name="Result Envelope", input_types=["Data", "JSON"], required=True),
        MessageTextInput(
            name="required_field",
            display_name="Required Success Field",
            value="",
            required=False,
            advanced=True,
            info="성공 경로에서 반드시 존재해야 하는 점 표기 payload 필드입니다.",
        ),
    ]
    outputs = [
        Output(name="success_path", display_name="Verified Success", method="route_result", types=["Data"], group_outputs=True),
        Output(name="blocked_path", display_name="Blocked Result", method="route_result", types=["Data"], group_outputs=True),
    ]

    def route_result(self) -> Data:
        result = getattr(self, "_gated_result", None)
        if not isinstance(result, dict):
            result = gate_result(
                getattr(self, "result", None),
                required_field=getattr(self, "required_field", ""),
            )
            self._gated_result = result
        selected = "success_path" if result.get("ok") is True else "blocked_path"
        for output_name in ("success_path", "blocked_path"):
            if output_name != selected:
                self.stop(output_name)
        self.status = {
            "ok": result.get("ok"),
            "status": result.get("status"),
            "route": selected,
            "required_field": str(getattr(self, "required_field", "") or ""),
        }
        return Data(data=copy.deepcopy(result))

from __future__ import annotations

import copy
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


PRIORITY_ORDER = {"safety": 0, "branch": 1, "contract": 2, "quality": 3}
FACT_STATUSES = {"confirmed", "inferred", "unknown", "conflicting"}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        payload = copy.deepcopy(value)
    else:
        data = getattr(value, "data", None)
        if isinstance(data, dict):
            payload = copy.deepcopy(data)
        else:
            text = getattr(value, "text", value if isinstance(value, str) else "")
            payload = json.loads(re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)) if isinstance(text, str) and text.strip() else {}
    nested = payload.get("work_definition")
    return copy.deepcopy(nested) if isinstance(nested, dict) else payload


def _fact_status(value: Any) -> str:
    if isinstance(value, dict) and value.get("status") in FACT_STATUSES and "value" in value:
        return str(value["status"])
    if value in (None, "", [], {}):
        return "unknown"
    if isinstance(value, list):
        item_statuses = []
        for item in value:
            provenance = item.get("provenance", {}) if isinstance(item, dict) else {}
            status = provenance.get("status") if isinstance(provenance, dict) else None
            if status in FACT_STATUSES:
                item_statuses.append(status)
        if "conflicting" in item_statuses:
            return "conflicting"
        if item_statuses and all(status == "confirmed" for status in item_statuses):
            return "confirmed"
        return "inferred"
    return "inferred"


def _plain_text(value: Any) -> str:
    if isinstance(value, dict) and "value" in value:
        value = value.get("value")
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, default=str).lower()
    return str(value or "").lower()


def _gap(code: str, path: str, priority: str, message: str, status: str = "unknown") -> dict[str, Any]:
    return {
        "reason_code": code,
        "target_paths": [path],
        "priority": priority,
        "current_status": status,
        "message": message,
    }


def evaluate_work_completeness(value: Any) -> dict[str, Any]:
    trace_id = f"trace-{uuid.uuid4()}"
    try:
        work = _payload(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        work = {}
    required_identity = ("work_definition_id", "tenant_id", "session_id", "revision")
    missing_identity = [key for key in required_identity if key not in work or work.get(key) in (None, "")]
    if missing_identity:
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_SCHEMA_INVALID", "message": "완전성 평가에 필요한 WorkDefinition 식별자가 없습니다.", "retryable": False, "details": {"fields": missing_identity}},
            "resume": None,
            "trace_id": trace_id,
        }
    try:
        revision = int(work["revision"])
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "BLOCKED",
            "artifact_refs": [],
            "error": {"code": "WORK_DEFINITION_REVISION_INVALID", "message": "완전성 평가 revision은 정수여야 합니다.", "retryable": False, "details": {}},
            "resume": None,
            "trace_id": trace_id,
        }

    gaps: list[dict[str, Any]] = []
    for field, code, message in (
        ("goal", "GOAL_UNKNOWN", "업무 목적과 완료 결과가 확인되지 않았습니다."),
        ("trigger", "TRIGGER_UNKNOWN", "업무 시작 조건 또는 주기가 확인되지 않았습니다."),
        ("inputs", "INPUT_CONTRACT_UNKNOWN", "핵심 입력과 형식이 확인되지 않았습니다."),
        ("outputs", "OUTPUT_CONTRACT_UNKNOWN", "핵심 출력과 전달 대상이 확인되지 않았습니다."),
        ("actors", "PRIMARY_ACTOR_UNKNOWN", "주요 수행자 또는 책임자가 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "contract", message, status))

    steps = work.get("steps") if isinstance(work.get("steps"), list) else []
    decisions = work.get("decisions") if isinstance(work.get("decisions"), list) else []
    all_text = " ".join(_plain_text(work.get(field)) for field in ("steps", "systems", "outputs", "risks_controls", "automation_intent"))
    write_or_send = bool(re.search(r"(저장|수정|삭제|발송|전송|등록|승인|write|update|delete|send|post)", all_text))
    sensitive = bool(re.search(r"(개인정보|민감|기밀|비밀번호|인증|토큰|secret|personal|restricted)", all_text))
    review_present = "human_review" in _plain_text(work.get("as_is_graph")) or bool(re.search(r"(사람|담당자|검토|승인|human.review)", _plain_text(work.get("risks_controls"))))
    if (write_or_send or sensitive) and not review_present:
        gaps.append(_gap("WRITE_APPROVAL_UNKNOWN" if write_or_send else "SENSITIVE_REVIEW_UNKNOWN", "risks_controls", "safety", "외부 변경·발송 또는 민감정보 처리 전에 필요한 권한과 사람 검토 위치가 확인되지 않았습니다."))

    if not steps:
        gaps.append(_gap("STEP_SEQUENCE_UNKNOWN", "steps", "branch", "업무 단계의 순서가 확인되지 않았습니다."))
    for decision_index, decision in enumerate(decisions):
        if not isinstance(decision, dict):
            gaps.append(_gap("DECISION_SCHEMA_INVALID", "decisions", "branch", "분기 정보 형식이 올바르지 않습니다.", "conflicting"))
            continue
        branches = decision.get("branches") or decision.get("outcomes")
        condition = decision.get("condition")
        if not condition or not isinstance(branches, list) or len(branches) < 2:
            gaps.append(_gap("BRANCH_CONDITION_UNKNOWN", f"decisions[{decision_index}]", "branch", "판단 조건과 두 개 이상의 분기 결과가 확인되지 않았습니다."))

    for field, code, message in (
        ("exceptions", "FAILURE_POLICY_UNKNOWN", "실패·예외 발생 시 처리 방식이 확인되지 않았습니다."),
        ("sla", "SLA_UNKNOWN", "기한 또는 허용 처리 시간이 확인되지 않았습니다."),
        ("success_criteria", "SUCCESS_CRITERIA_UNKNOWN", "완료 품질을 판단할 측정 기준이 확인되지 않았습니다."),
    ):
        status = _fact_status(work.get(field))
        if status in {"unknown", "conflicting"}:
            gaps.append(_gap(code, field, "quality", message, status))

    scope_in = {_plain_text(item) for item in (work.get("scope_in") or [])}
    scope_out = {_plain_text(item) for item in (work.get("scope_out") or [])}
    overlap = sorted(text for text in scope_in & scope_out if text)
    if overlap:
        gaps.append({**_gap("SCOPE_CONFLICT", "scope_in", "branch", "포함 범위와 제외 범위가 충돌합니다.", "conflicting"), "conflicting_values": overlap[:20]})

    gaps.sort(key=lambda item: (PRIORITY_ORDER.get(item["priority"], 99), item["reason_code"], item["target_paths"][0]))
    blocking = bool(gaps)
    result_status = "NEEDS_CLARIFICATION" if blocking else "READY_FOR_REVIEW"
    evaluation = {
        "work_definition_id": work["work_definition_id"],
        "tenant_id": work["tenant_id"],
        "session_id": work["session_id"],
        "revision": revision,
        "channel_mode": work.get("channel_mode"),
        "needs_clarification": blocking,
        "blocking_gap_count": len(gaps),
        "blocking_gaps": gaps,
        "question_policy": {"max_questions_per_round": 3, "priority_order": ["safety", "branch", "contract", "quality"]},
    }
    return {
        "ok": True,
        "status": result_status,
        "artifact_refs": [{"kind": "work_definition", "id": work["work_definition_id"], "revision": revision}],
        "completeness": evaluation,
        "trace_id": trace_id,
    }


